namespace SrpLab;
public sealed class TicketPriorityClassifier { public string Classify(string subject, string body) { var text=(subject+" "+body).ToLowerInvariant(); if(text.Contains("down")||text.Contains("outage")||text.Contains("cannot login")) return "P1"; if(text.Contains("urgent")||text.Contains("asap")||text.Contains("blocked")) return "P2"; return "P3"; } }
public sealed class SlaDeadlinePolicy { public DateTimeOffset Deadline(string priority, DateTimeOffset openedAt) { var hours=priority=="P1"?4:priority=="P2"?24:72; return openedAt.AddHours(hours); } }
public sealed class PublicReplyComposer { public string Compose(string id,string priority,string agent,DateTimeOffset deadline) { var apology=priority=="P1"?"We are treating this as a critical incident.":"Thanks for reaching out."; return $"Hi,\n{apology}\nTicket {id} is with {agent}. Next update before {deadline:u}.\n"; } }
public sealed class EscalationBlurbFormatter { public string Format(string id,string priority,DateTimeOffset deadline) { return $"ESCALATE {id} priority={priority} breachAt={deadline:u} keywords-scanned=yes"; } }
